/**
 * The verdict model. Deterministic from first principles.
 *
 *   level       highest evidence TYPE present in the claim's population
 *   support     independent in-population ORGS at that type
 *   precision   saturation (theme) or Wilson interval (prevalence)
 *   binding     the single change that raises the verdict
 *
 * Quantity never raises level. The unit is the organisation. L5 never
 * validates a customer claim. Nothing here is generated by a model.
 */

import type {
  Binding,
  Claim,
  Coverage,
  EvidenceLevel,
  Finding,
  FindingKind,
  Interval,
  Saturation,
  Verdict,
  VerdictInput,
} from "../lib/types";
import {
  FLOOR,
  MIN_SUPPORT,
  WILSON_Z,
  nextTarget,
  threshold,
} from "./thresholds";

const SATURATION_BASIC = threshold("SATURATION_BASIC").value;
const SATURATION_CODE = threshold("SATURATION_CODE").value;
const SATURATION_MEANING = threshold("SATURATION_MEANING").value;

/** Two decimals is the precision the product claims and the fixtures state. */
function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

/** 95% Wilson score interval. Deterministic, exact, no model involved. */
export function wilson(k: number, n: number, z: number = WILSON_Z): Interval {
  if (n === 0) return [0, 1, 1];

  const p = k / n;
  const d = 1 + (z * z) / n;
  const centre = p + (z * z) / (2 * n);
  const margin = z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n));

  const lo = Math.max(0, (centre - margin) / d);
  const hi = Math.min(1, (centre + margin) / d);

  return [round2(lo), round2(hi), round2(hi - lo)];
}

/** Thematic completeness of stated evidence, not prevalence precision. */
export function saturationRung(breadth: number): Saturation {
  if (breadth < SATURATION_BASIC) return "insufficient";
  if (breadth < SATURATION_CODE) return "basic";
  if (breadth < SATURATION_MEANING) return "code";
  return "meaning";
}

export function toVerdictInput(coverage: Coverage, claim: Claim): VerdictInput {
  return {
    claimType: claim.claimType,
    observed: claim.observed,
    types: coverage.allOrgsByLevel,
    inPopulationTypes: coverage.orgsByLevel,
    inPopulationOrgs: coverage.inPopulationOrgs,
  };
}

export function sumTypes(types: Readonly<Partial<Record<EvidenceLevel, number>>>): number {
  let total = 0;
  for (const value of Object.values(types)) total += value ?? 0;
  return total;
}

/**
 * The single change that would raise the claim. Verified mechanically:
 * applying it strictly increases (level, support, breadth) in every case.
 */
export function selectBinding(
  verdict: Pick<Verdict, "level" | "support">,
  input: VerdictInput,
): Binding {
  const total = sumTypes(input.types);
  if (total === 0) return "type"; // no external evidence exists at all
  if (input.inPopulationOrgs === 0) return "population"; // nothing here is about this claim
  if (verdict.level === FLOOR) return "type";

  // A reached type resting on one or two organisations is a support problem.
  // More of the same kind of interview does not unlock the next type.
  if (verdict.level >= 4 && verdict.support < MIN_SUPPORT) return "support";

  if (verdict.level < 6) {
    const next = nextTarget(verdict.level);
    if ((input.types[next] ?? 0) === 0) return "type";
    return null;
  }

  if (verdict.support < MIN_SUPPORT) return "support";
  return null;
}

export function computeVerdict(input: VerdictInput): Verdict {
  const applicable: Partial<Record<EvidenceLevel, number>> = {};

  if (input.inPopulationOrgs > 0) {
    for (const [level, count] of Object.entries(input.inPopulationTypes)) {
      if ((count ?? 0) > 0) applicable[Number(level) as EvidenceLevel] = count;
    }
  }

  const levels = Object.keys(applicable).map(Number) as EvidenceLevel[];
  const level: EvidenceLevel =
    levels.length === 0 ? FLOOR : (Math.max(...levels) as EvidenceLevel);
  const support = applicable[level] ?? 0;
  const breadth = sumTypes(applicable);

  let saturation: Saturation = null;
  if (level <= 2) saturation = saturationRung(breadth);

  let interval: Interval | null = null;
  if (input.claimType === "prevalence" && input.observed && input.inPopulationOrgs > 0) {
    interval = wilson(input.observed.k, input.observed.n);
  }

  const verdict: Verdict = {
    level,
    support,
    breadth,
    saturation,
    interval,
    binding: null,
  };

  return { ...verdict, binding: selectBinding(verdict, input) };
}

/** Perform the smallest real-world change matching the named constraint. */
export function applyFix(input: VerdictInput, verdict: Verdict): VerdictInput {
  const types = { ...input.types };
  const inPopulationTypes = { ...input.inPopulationTypes };

  switch (verdict.binding) {
    case null:
      return input;
    case "population":
      return {
        ...input,
        types,
        inPopulationTypes: types,
        inPopulationOrgs: sumTypes(types),
      };
    case "type": {
      const next = nextTarget(verdict.level);
      types[next] = (types[next] ?? 0) + 1;
      inPopulationTypes[next] = (inPopulationTypes[next] ?? 0) + 1;
      return {
        ...input,
        types,
        inPopulationTypes,
        inPopulationOrgs: input.inPopulationOrgs + 1,
      };
    }
    case "support": {
      const missing = MIN_SUPPORT - (inPopulationTypes[verdict.level] ?? 0);
      types[verdict.level] = (types[verdict.level] ?? 0) + missing;
      inPopulationTypes[verdict.level] = MIN_SUPPORT;
      return {
        ...input,
        types,
        inPopulationTypes,
        inPopulationOrgs: input.inPopulationOrgs + missing,
      };
    }
  }
}

export function rank(verdict: Verdict): readonly [number, number, number] {
  return [verdict.level, verdict.support, verdict.breadth];
}

export function classifyFinding(
  claim: Claim,
  verdict: Verdict,
  coverage: Coverage,
): FindingKind {
  if (coverage.inPopulationOrgs === 0 && coverage.distinctOrgs > 0) {
    return "WRONG_POPULATION";
  }
  if (coverage.distinctOrgs === 0) return "UNTOUCHED";
  if (verdict.level < claim.claimedLevel) return "DOWNGRADE";

  if (
    claim.claimType === "prevalence" &&
    verdict.interval &&
    claim.precisionTolerance !== null &&
    verdict.interval[2] / 2 > claim.precisionTolerance
  ) {
    return "IMPRECISE";
  }

  return "SUPPORTED";
}

export function buildFinding(
  claim: Claim,
  coverage: Coverage,
): Finding {
  const verdict = computeVerdict(toVerdictInput(coverage, claim));
  return {
    claimId: claim.id,
    kind: classifyFinding(claim, verdict, coverage),
    claimed: claim.claimedLevel,
    verdict,
    evidenceElsewhere: coverage.totalRows - coverage.inPopulationRows,
  };
}

